DROP TABLE IF EXISTS taxonomy_item_field_value;

-- DROP SEQUENCE IF EXISTS taxonomy_item_field_value_taxonomy_item_field_value_id_seq;
-- CREATE SEQUENCE taxonomy_item_field_value_taxonomy_item_field_value_id_seq;


CREATE TABLE taxonomy_item_field_value (
  "taxonomy_item_field_value_id" int PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, -- SERIAL PRIMARY KEY,
  "language_id" int NOT NULL,
  "taxonomy_item_id" int NOT NULL,
  "field_id" int NOT NULL,
  "sort_order" int NOT NULL DEFAULT 0
  -- PRIMARY KEY("taxonomy_item_field_value_id")
);

-- SELECT setval('taxonomy_item_field_value_taxonomy_item_field_value_id_seq', 0, true); -- last inserted id by sample data

CREATE INDEX IF NOT EXISTS "taxonomy_item_field_value_field" ON taxonomy_item_field_value ("field_id");
